export type CreateMswHandlersResult = {
  all: (options?: {
    pick?: {
      [K in keyof MswHandlerFactories]?:
        | Parameters<MswHandlerFactories[K]>[0]
        | Parameters<MswHandlerFactories[K]>;
    };
  }) => ReadonlyArray<HttpHandler>;
  pick: MswHandlerFactories;
};

export function createMswHandlers(
  config: RequestHandlerOptions = {}
): CreateMswHandlersResult {
  type Handler<R> = (
    response?: R,
    options?: RequestHandlerOptions
  ) => HttpHandler;
  function wrap<R>(handler: Handler<R>): Handler<R> {
    return (response, options) => handler(response, { ...config, ...options });
  }
  const pick: CreateMswHandlersResult['pick'] = {
    isSetup: wrap(handleIsSetup),
    completeSetup: wrap(handleCompleteSetup),
    getOidcSettings: wrap(handleGetOidcSettings),
    initOidc: wrap(handleInitOidc),
    key: wrap(handleKey),
    authenticate: wrap(handleAuthenticate),
    logout: wrap(handleLogout),
    testToken: wrap(handleTestToken),
    authConfig: wrap(handleAuthConfig),
    updatePassword: wrap(handleUpdatePassword),
    startEmailChange: wrap(handleStartEmailChange),
    updateAccount: wrap(handleUpdateAccount),
    confirmEmailChange: wrap(handleConfirmEmailChange),
    updateAvatar: wrap(handleUpdateAvatar),
    info: wrap(handleInfo),
    avatarById: wrap(handleAvatarById),
    resetUserAvatar: wrap(handleResetUserAvatar),
    deleteUser: wrap(handleDeleteUser),
    listUsers: wrap(handleListUsers),
    createUser: wrap(handleCreateUser),
    editUser: wrap(handleEditUser),
    userInfo: wrap(handleUserInfo),
    mailActive: wrap(handleMailActive),
    listGroupsSimple: wrap(handleListGroupsSimple),
    resetUserPassword: wrap(handleResetUserPassword),
    changeUserEmail: wrap(handleChangeUserEmail),
    convertOidcUser: wrap(handleConvertOidcUser),
    getGeneralSettings: wrap(handleGetGeneralSettings),
    getUserSettings: wrap(handleGetUserSettings),
    saveUserSettings: wrap(handleSaveUserSettings),
    getMailSettings: wrap(handleGetMailSettings),
    saveMailSettings: wrap(handleSaveMailSettings),
    sendResetLink: wrap(handleSendResetLink),
    resetPassword: wrap(handleResetPassword),
    testMail: wrap(handleTestMail),
    deleteGroup: wrap(handleDeleteGroup),
    listGroups: wrap(handleListGroups),
    createGroup: wrap(handleCreateGroup),
    editGroup: wrap(handleEditGroup),
    groupInfo: wrap(handleGroupInfo),
    listUsersSimple: wrap(handleListUsersSimple),
    deleteNode: wrap(handleDeleteNode),
    listNodes: wrap(handleListNodes),
    createNode: wrap(handleCreateNode),
    nodeInfo: wrap(handleNodeInfo),
    updateNode: wrap(handleUpdateNode),
    nodeTokenRegenerate: wrap(handleNodeTokenRegenerate),
    deleteEgg: wrap(handleDeleteEgg),
    listEggs: wrap(handleListEggs),
    createEgg: wrap(handleCreateEgg),
    editEgg: wrap(handleEditEgg),
    eggInfo: wrap(handleEggInfo),
    eggSource: wrap(handleEggSource),
    listServers: wrap(handleListServers),
    createServer: wrap(handleCreateServer),
    serverOptions: wrap(handleServerOptions),
    deleteServer: wrap(handleDeleteServer),
    serverInfo: wrap(handleServerInfo),
    updateServer: wrap(handleUpdateServer),
    reinstallServer: wrap(handleReinstallServer),
    setServerInstalled: wrap(handleSetServerInstalled),
    setServerSuspended: wrap(handleSetServerSuspended),
    transferServer: wrap(handleTransferServer),
    serverPower: wrap(handleServerPower),
    serverCommand: wrap(handleServerCommand),
    serverWs: wrap(handleServerWs),
    listFiles: wrap(handleListFiles),
    fileContent: wrap(handleFileContent),
    writeFileContent: wrap(handleWriteFileContent),
    createFolder: wrap(handleCreateFolder),
    createFile: wrap(handleCreateFile),
    renameFile: wrap(handleRenameFile),
    copyFile: wrap(handleCopyFile),
    deleteFiles: wrap(handleDeleteFiles),
    downloadFile: wrap(handleDownloadFile),
    startUpload: wrap(handleStartUpload),
    cancelUpload: wrap(handleCancelUpload),
    completeUpload: wrap(handleCompleteUpload),
    uploadChunk: wrap(handleUploadChunk),
    listBackups: wrap(handleListBackups),
    createBackup: wrap(handleCreateBackup),
    deleteBackup: wrap(handleDeleteBackup),
    lockBackup: wrap(handleLockBackup),
    restoreBackup: wrap(handleRestoreBackup),
    downloadBackup: wrap(handleDownloadBackup),
    listSchedules: wrap(handleListSchedules),
    createSchedule: wrap(handleCreateSchedule),
    deleteSchedule: wrap(handleDeleteSchedule),
    scheduleInfo: wrap(handleScheduleInfo),
    updateSchedule: wrap(handleUpdateSchedule),
    runSchedule: wrap(handleRunSchedule),
    createScheduleTask: wrap(handleCreateScheduleTask),
    deleteScheduleTask: wrap(handleDeleteScheduleTask),
    updateScheduleTask: wrap(handleUpdateScheduleTask)
  };
  const all: CreateMswHandlersResult['all'] = (options = {}) => {
    type OverrideValue<R> = R | [response?: R, options?: RequestHandlerOptions];
    function invoke<R>(
      fn: Handler<R>,
      override?: OverrideValue<R>
    ): HttpHandler {
      return Array.isArray(override) ? fn(...override) : fn(override);
    }
    const overrides = options.pick ?? {};
    return [
      invoke(pick.completeUpload, overrides.completeUpload),
      invoke(pick.uploadChunk, overrides.uploadChunk),
      invoke(pick.deleteScheduleTask, overrides.deleteScheduleTask),
      invoke(pick.updateScheduleTask, overrides.updateScheduleTask),
      invoke(pick.cancelUpload, overrides.cancelUpload),
      invoke(pick.lockBackup, overrides.lockBackup),
      invoke(pick.restoreBackup, overrides.restoreBackup),
      invoke(pick.downloadBackup, overrides.downloadBackup),
      invoke(pick.runSchedule, overrides.runSchedule),
      invoke(pick.createScheduleTask, overrides.createScheduleTask),
      invoke(pick.avatarById, overrides.avatarById),
      invoke(pick.fileContent, overrides.fileContent),
      invoke(pick.writeFileContent, overrides.writeFileContent),
      invoke(pick.createFolder, overrides.createFolder),
      invoke(pick.createFile, overrides.createFile),
      invoke(pick.renameFile, overrides.renameFile),
      invoke(pick.copyFile, overrides.copyFile),
      invoke(pick.deleteFiles, overrides.deleteFiles),
      invoke(pick.downloadFile, overrides.downloadFile),
      invoke(pick.startUpload, overrides.startUpload),
      invoke(pick.deleteBackup, overrides.deleteBackup),
      invoke(pick.deleteSchedule, overrides.deleteSchedule),
      invoke(pick.scheduleInfo, overrides.scheduleInfo),
      invoke(pick.updateSchedule, overrides.updateSchedule),
      invoke(pick.updatePassword, overrides.updatePassword),
      invoke(pick.startEmailChange, overrides.startEmailChange),
      invoke(pick.updateAccount, overrides.updateAccount),
      invoke(pick.confirmEmailChange, overrides.confirmEmailChange),
      invoke(pick.updateAvatar, overrides.updateAvatar),
      invoke(pick.resetUserAvatar, overrides.resetUserAvatar),
      invoke(pick.mailActive, overrides.mailActive),
      invoke(pick.listGroupsSimple, overrides.listGroupsSimple),
      invoke(pick.resetUserPassword, overrides.resetUserPassword),
      invoke(pick.changeUserEmail, overrides.changeUserEmail),
      invoke(pick.convertOidcUser, overrides.convertOidcUser),
      invoke(pick.sendResetLink, overrides.sendResetLink),
      invoke(pick.resetPassword, overrides.resetPassword),
      invoke(pick.userInfo, overrides.userInfo),
      invoke(pick.nodeTokenRegenerate, overrides.nodeTokenRegenerate),
      invoke(pick.eggSource, overrides.eggSource),
      invoke(pick.reinstallServer, overrides.reinstallServer),
      invoke(pick.setServerInstalled, overrides.setServerInstalled),
      invoke(pick.setServerSuspended, overrides.setServerSuspended),
      invoke(pick.transferServer, overrides.transferServer),
      invoke(pick.serverPower, overrides.serverPower),
      invoke(pick.serverCommand, overrides.serverCommand),
      invoke(pick.serverWs, overrides.serverWs),
      invoke(pick.listFiles, overrides.listFiles),
      invoke(pick.listBackups, overrides.listBackups),
      invoke(pick.createBackup, overrides.createBackup),
      invoke(pick.listSchedules, overrides.listSchedules),
      invoke(pick.createSchedule, overrides.createSchedule),
      invoke(pick.getOidcSettings, overrides.getOidcSettings),
      invoke(pick.initOidc, overrides.initOidc),
      invoke(pick.key, overrides.key),
      invoke(pick.authenticate, overrides.authenticate),
      invoke(pick.logout, overrides.logout),
      invoke(pick.testToken, overrides.testToken),
      invoke(pick.authConfig, overrides.authConfig),
      invoke(pick.info, overrides.info),
      invoke(pick.deleteUser, overrides.deleteUser),
      invoke(pick.listUsers, overrides.listUsers),
      invoke(pick.createUser, overrides.createUser),
      invoke(pick.editUser, overrides.editUser),
      invoke(pick.getGeneralSettings, overrides.getGeneralSettings),
      invoke(pick.getUserSettings, overrides.getUserSettings),
      invoke(pick.saveUserSettings, overrides.saveUserSettings),
      invoke(pick.getMailSettings, overrides.getMailSettings),
      invoke(pick.saveMailSettings, overrides.saveMailSettings),
      invoke(pick.testMail, overrides.testMail),
      invoke(pick.listUsersSimple, overrides.listUsersSimple),
      invoke(pick.serverOptions, overrides.serverOptions),
      invoke(pick.groupInfo, overrides.groupInfo),
      invoke(pick.nodeInfo, overrides.nodeInfo),
      invoke(pick.updateNode, overrides.updateNode),
      invoke(pick.eggInfo, overrides.eggInfo),
      invoke(pick.deleteServer, overrides.deleteServer),
      invoke(pick.serverInfo, overrides.serverInfo),
      invoke(pick.updateServer, overrides.updateServer),
      invoke(pick.isSetup, overrides.isSetup),
      invoke(pick.completeSetup, overrides.completeSetup),
      invoke(pick.deleteGroup, overrides.deleteGroup),
      invoke(pick.listGroups, overrides.listGroups),
      invoke(pick.createGroup, overrides.createGroup),
      invoke(pick.editGroup, overrides.editGroup),
      invoke(pick.deleteNode, overrides.deleteNode),
      invoke(pick.listNodes, overrides.listNodes),
      invoke(pick.createNode, overrides.createNode),
      invoke(pick.deleteEgg, overrides.deleteEgg),
      invoke(pick.listEggs, overrides.listEggs),
      invoke(pick.createEgg, overrides.createEgg),
      invoke(pick.editEgg, overrides.editEgg),
      invoke(pick.listServers, overrides.listServers),
      invoke(pick.createServer, overrides.createServer)
    ];
  };
  return { all, pick };
}
